mapper.select:
select r.id, r.registration_no as registrationNo, r.season_id as seasonId, r.team_id as teamId, r.registration_status as registrationStatus, r.lineup_count as lineupCount, r.submitted_time as submittedTime, tm.tournament_name as tournamentName, t.team_name as teamName, ifnull(nullif(cp.game_nickname, ''), r.contact_name) as captainName from basket_tournament_registration r left join basket_team t on t.id = r.team_id and t.is_delete = 0 left join basket_tournament_season s on s.id = r.season_id and s.is_delete = 0 left join basket_tournament tm on tm.id = s.tournament_id and tm.is_delete = 0 left join basket_player_profile cp on cp.id = r.captain_player_id and cp.is_delete = 0 where r.is_delete = 0 and r.registration_status != 0 and r.registration_no like concat('%', #{registrationNo}, '%') and r.season_id = #{seasonId} and r.team_id = #{teamId}
and r.registration_status in (1, 2) and r.registration_status = 3 and r.registration_status = 4 and r.registration_status in (5, 6)
and r.registration_status in (1, 2)
and r.registration_status in (5, 6)
and r.registration_status = #{registrationStatus}
order by r.submitted_time desc, r.create_time desc
